package com.nigson.acceptance.pricing;
import com.nigson.commerce.pricing.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.security.ActorAssertion;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.junit.jupiter.api.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class PricingPersistenceTest {
 PricingFixture f;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"pricing-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new PricingFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 @Test void draftCannotSupplyPublicPriceAndCurrentRolePrecedesReplay(){var input=f.input("12.34");var draft=f.books.create(f.sales,input,"create",UUID.randomUUID());assertThat(draft.active()).isFalse();assertThat(draft.revision()).isEqualTo(1);assertThat(draft.version()).isZero();assertThat(f.books.create(f.sales,input,"create",UUID.randomUUID())).isEqualTo(draft);assertThatThrownBy(()->f.books.create(f.sales,f.input("12.35"),"create",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThatThrownBy(()->f.books.create(f.finance,input,"other",UUID.randomUUID())).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->f.prices.price(null,f.sku,"NG","2",null)).hasMessage("PRICING_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='SALES'",f.sales.party());assertThatThrownBy(()->f.books.create(f.sales,input,"create",UUID.randomUUID())).hasMessage("ACCESS_DENIED");}
 @Test void quantityTierSelectionAndPackAreCurrentAndNeverFallback(){var active=f.retail();assertThat(f.prices.price(null,f.sku,"NG","2",null).unitAmount()).isEqualTo("12.34");assertThat(f.prices.price(null,f.sku,"NG","10",null).unitAmount()).isEqualTo("1.00");assertThatThrownBy(()->f.prices.price(null,f.sku,"NG","1.001",null)).hasMessage("PRICING_RULE_VIOLATION");assertThatThrownBy(()->f.prices.price(null,f.sku,"NG","2",UUID.randomUUID())).hasMessage("AUTH_REQUIRED");f.jdbc.update("UPDATE commerce.price_book SET effective_until=now()-interval '1 second' WHERE id=?",active.id());assertThatThrownBy(()->f.prices.price(null,f.sku,"NG","2",null)).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void activationNeedsFreshFinanceAndEmitsOneAtomicEvent(){var book=f.books.create(f.sales,f.input("12.34"),"create",UUID.randomUUID());var stale=new ActorAssertion.Actor(f.finance.party(),f.finance.identityIssuer(),f.finance.identitySubject(),null,Set.of("FINANCE"),Set.of(),Instant.now().minusSeconds(901));assertThatThrownBy(()->f.books.activate(stale,book.id(),0,"Synthetic reviewed offline activation","stale",UUID.randomUUID())).hasMessage("ACTOR_TRUST_REJECTED");var active=f.books.activate(f.finance,book.id(),0,"Synthetic reviewed offline activation","activate",UUID.randomUUID());assertThat(f.books.activate(f.finance,book.id(),0,"Synthetic reviewed offline activation","activate",UUID.randomUUID())).isEqualTo(active);assertThatThrownBy(()->f.books.activate(f.finance,book.id(),0,"Synthetic reviewed offline activation","old",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,book.id())).isEqualTo(1);var event=EventCodec.decode(f.jdbc.queryForObject("SELECT payload::text FROM commerce.outbox_event WHERE aggregate_id=?",String.class,book.id()));assertThat(event.get("event_type").asString()).isEqualTo("pricing.changed.v1");assertThat(event.get("payload").get("revision").asLong()).isEqualTo(1);assertThat(f.metrics.get("nigson.pricing.commands").tag("operation","ACTIVATE").counter().count()).isEqualTo(1);}
 @Test void publishedPriceEntriesRemainByteForByteAfterCopyOnWrite(){var active=f.retail();String before=f.jdbc.queryForObject("SELECT jsonb_agg(to_jsonb(e) ORDER BY id)::text FROM commerce.price_entry e WHERE price_book_id=?",String.class,active.id());var input=new PricingValues.Input(null,"NGN","RETAIL",active.effectiveUntil(),active.effectiveUntil().plusSeconds(3600),List.of(new PricingValues.Entry(f.sku,"1","20.00")));var next=f.books.revise(f.sales,active.id(),1,input,"revise",UUID.randomUUID());assertThat(next.id()).isNotEqualTo(active.id());assertThat(next.revision()).isEqualTo(2);assertThat(next.active()).isFalse();assertThat(f.jdbc.queryForObject("SELECT jsonb_agg(to_jsonb(e) ORDER BY id)::text FROM commerce.price_entry e WHERE price_book_id=?",String.class,active.id())).isEqualTo(before);assertThat(f.prices.price(null,f.sku,"NG","2",null).unitAmount()).isEqualTo("12.34");assertThatThrownBy(()->f.books.revise(f.sales,active.id(),1,input,"stale-parent",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThat(f.books.activate(f.finance,next.id(),0,"Synthetic future revision activation","activate-next",UUID.randomUUID()).active()).isTrue();}
 @Test void bookValidationRejectsWrongScaleMissingSkuAndActiveIntervalOverlap(){assertThatThrownBy(()->f.books.create(f.sales,f.input("1.000"),"third",UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");var input=f.input("1.00");var bad=new PricingValues.Input(f.code,"NGN","RETAIL",input.effectiveFrom(),input.effectiveUntil(),List.of(new PricingValues.Entry(UUID.randomUUID(),"1","1.00")));assertThatThrownBy(()->f.books.create(f.sales,bad,"missing-sku",UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");var one=f.books.create(f.sales,input,"one",UUID.randomUUID());var next=new PricingValues.Input(null,"NGN","RETAIL",one.effectiveFrom().plusSeconds(60),one.effectiveUntil(),one.entries());var two=f.books.revise(f.sales,one.id(),0,next,"two",UUID.randomUUID());f.books.activate(f.finance,one.id(),0,"Synthetic first interval activation","activate-one",UUID.randomUUID());assertThatThrownBy(()->f.books.activate(f.finance,two.id(),0,"Synthetic overlapping activation","activate-two",UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void quoteIsImmutableExactAndDoesNotReserveStock(){f.retail();var q=f.quotes.create(f.customer,f.quoteInput(),"quote",UUID.randomUUID());assertThat(q.totals().subtotal()).isEqualTo("24.68");assertThat(q.totals().grandTotal()).isEqualTo("28.13");assertThat(q.lines().getFirst().unitAmount()).isEqualTo("12.34");assertThat(q.expiresAt()).isBeforeOrEqualTo(Instant.now().plusSeconds(300));assertThat(f.jdbc.queryForObject("SELECT expires_at FROM commerce.checkout_quote WHERE id=?",java.sql.Timestamp.class,q.id()).toInstant()).isEqualTo(q.expiresAt());var snapshot=f.jdbc.queryForObject("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",String.class,q.id());assertThat(EventCodec.hash(EventCodec.JSON.readTree(snapshot))).isEqualTo(q.quoteHash());assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_reservation r JOIN commerce.inventory_balance b ON b.id=r.balance_id WHERE b.sku_id=?",Integer.class,f.sku)).isZero();f.jdbc.update("UPDATE commerce.price_entry SET unit_amount=99 WHERE sku_id=?",f.sku);assertThat(f.quotes.create(f.customer,f.quoteInput(),"quote",UUID.randomUUID())).isEqualTo(q);assertThat(f.jdbc.queryForObject("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",String.class,q.id())).isEqualTo(snapshot);assertThatThrownBy(()->f.jdbc.update("UPDATE commerce.checkout_quote SET price_snapshot='{}'::jsonb WHERE id=?",q.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void carrierBindingRejectsStaleCartAddressPackageExpiryAndProviderMode(){f.retail();for(String command:List.of("UPDATE commerce.cart SET version=1 WHERE id=?","UPDATE commerce.address SET line1='Changed synthetic offline address' WHERE id=?","UPDATE commerce.sku SET carrier_packaging=jsonb_set(carrier_packaging,'{unitWeightKg}','\"2\"'::jsonb) WHERE id=?","UPDATE commerce.carrier_quote SET expires_at=now()-interval '1 second' WHERE id=?")){UUID target=command.contains("commerce.cart ")?f.cart:command.contains("commerce.address")?f.address:command.contains("commerce.sku")?f.sku:f.carrier;var tx=new org.springframework.transaction.support.TransactionTemplate(f.manager);tx.execute(s->{f.jdbc.update(command,target);assertThatThrownBy(()->f.quotes.create(f.customer,f.quoteInput(),UUID.randomUUID().toString(),UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");s.setRollbackOnly();return null;});}f.jdbc.update("UPDATE commerce.carrier_quote SET mode='LIVE' WHERE id=?",f.carrier);assertThatThrownBy(()->f.quotes.create(f.customer,f.quoteInput(),"wrong-mode",UUID.randomUUID())).hasMessage("PROVIDER_MODE_MISMATCH");}
 @Test void quoteAndActivationAuditFailureRollBackAllEffects(){var book=f.books.create(f.sales,f.input("12.34"),"create",UUID.randomUUID());f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.books.activate(f.finance,book.id(),0,"Synthetic audit rollback activation","activate",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT active FROM commerce.price_book WHERE id=?",Boolean.class,book.id())).isFalse();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,book.id())).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}f.books.activate(f.finance,book.id(),0,"Synthetic audit rollback activation","activate",UUID.randomUUID());f.jdbc.update("UPDATE commerce.market SET retail_price_book_id=? WHERE id=?",book.id(),f.market);f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.quotes.create(f.customer,f.quoteInput(),"quote",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.checkout_quote WHERE cart_id=?",Integer.class,f.cart)).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.quotes.create(f.customer,f.quoteInput(),"quote",UUID.randomUUID()).id()).isNotNull();}
 @Test void twelveDuplicateQuotesProduceOneSnapshotAuditAndMetric()throws Exception{f.retail();var start=new CyclicBarrier(12);var ids=new HashSet<UUID>();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var futures=new ArrayList<Future<UUID>>();for(int i=0;i<12;i++)futures.add(pool.submit(()->{start.await();try{return f.quotes.create(f.customer,f.quoteInput(),"same-quote",UUID.randomUUID()).id();}catch(com.nigson.commerce.platform.PlatformStore.Conflict busy){assertThat(busy.getMessage()).isEqualTo("IDEMPOTENCY_IN_PROGRESS");return null;}}));for(var value:futures){UUID id=value.get(15,TimeUnit.SECONDS);if(id!=null)ids.add(id);}ids.add(f.quotes.create(f.customer,f.quoteInput(),"same-quote",UUID.randomUUID()).id());}assertThat(ids).hasSize(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.checkout_quote WHERE cart_id=?",Integer.class,f.cart)).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CHECKOUT_QUOTE'",Integer.class,ids.iterator().next())).isEqualTo(1);assertThat(f.metrics.get("nigson.pricing.commands").tag("operation","QUOTE").counter().count()).isEqualTo(1);}
 @Test void concurrentRevisionCommandsCannotAssignOneRevisionTwice()throws Exception{var one=f.retail();var input=new PricingValues.Input(null,"NGN","RETAIL",one.effectiveUntil(),one.effectiveUntil().plusSeconds(3600),List.of(new PricingValues.Entry(f.sku,"1","20.00")));var barrier=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++){String key="revision-"+i;futures.add(pool.submit(()->{barrier.await();try{f.books.revise(f.sales,one.id(),1,input,key,UUID.randomUUID());return true;}catch(com.nigson.shared.problem.Problem.Failure stale){assertThat(stale.getMessage()).isEqualTo("VERSION_MISMATCH");return false;}}));}int accepted=0;for(var result:futures)if(result.get(10,TimeUnit.SECONDS))accepted++;assertThat(accepted).isEqualTo(1);}assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.price_book WHERE code=?",Integer.class,f.code)).isEqualTo(2);}
 @Test void approvedOfferPricesPrecedeCurrentRetailAndRemainFrozen(){var retail=f.retail();UUID offered=f.offer();f.jdbc.update("UPDATE commerce.price_entry SET unit_amount=99 WHERE price_book_id=?",retail.id());var result=f.quotes.create(f.customer,f.quoteInput(),"offered",UUID.randomUUID());assertThat(result.lines().getFirst().unitAmount()).isEqualTo("5.00");assertThat(result.totals().grandTotal()).isEqualTo("13.45");assertThat(result.expiresAt()).isBeforeOrEqualTo(Instant.now().plusSeconds(120));f.jdbc.update("UPDATE commerce.quote_revision SET approval_status='REJECTED' WHERE id=?",offered);assertThatThrownBy(()->f.quotes.create(f.customer,f.quoteInput(),"rejected-offer",UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void organizationRequiresExactCurrentEntitlementAndWholesaleAssignment(){f.retail();UUID org=f.organization();assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","2",org)).hasMessage("PRICING_RULE_VIOLATION");var input=f.input("12.34");var wholesale=new PricingValues.Input(f.code+"_W","NGN","DISTRIBUTOR",input.effectiveFrom(),input.effectiveUntil(),List.of(new PricingValues.Entry(f.sku,"1","8.00")));var draft=f.books.create(f.sales,wholesale,"wholesale",UUID.randomUUID());var book=f.books.activate(f.finance,draft.id(),0,"Synthetic wholesale activation","activate-wholesale",UUID.randomUUID());f.jdbc.update("INSERT INTO commerce.price_assignment(id,created_by,updated_by,organization_id,market_id,price_book_id) VALUES (?,'test','test',?,?,?)",UUID.randomUUID(),org,f.market,book.id());f.jdbc.update("INSERT INTO commerce.wholesale_rule(id,created_by,updated_by,organization_id,sku_id,market_id,minimum_quantity,pack_multiple,minimum_order_amount,rule_revision) VALUES (?,'test','test',?,?,?,2,2,16,1)",UUID.randomUUID(),org,f.sku,f.market);assertThat(f.prices.price(f.customer,f.sku,"NG","2",org).unitAmount()).isEqualTo("8.00");assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","1",org)).hasMessage("PRICING_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.cart SET organization_id=? WHERE id=?",org,f.cart);assertThat(f.quotes.create(f.customer,f.quoteInput(),"org-quote",UUID.randomUUID()).totals().grandTotal()).isEqualTo("19.45");f.jdbc.update("UPDATE commerce.account_entitlement SET status='SUSPENDED' WHERE organization_id=?",org);assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","2",org)).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->f.quotes.create(f.customer,f.quoteInput(),"org-quote",UUID.randomUUID())).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.account_entitlement SET status='ACTIVE' WHERE organization_id=?",org);f.jdbc.update("UPDATE commerce.price_assignment SET active=false WHERE organization_id=?",org);assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","2",org)).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void serverRepositoryAndStaffPageRespectHundredEntryCap(){var entries=new ArrayList<PricingValues.Entry>();for(int quantity=1;quantity<=100;quantity++)entries.add(new PricingValues.Entry(f.sku,Integer.toString(quantity),"1.00"));var base=f.input("1.00");var input=new PricingValues.Input(f.code,"NGN","RETAIL",base.effectiveFrom(),base.effectiveUntil(),entries);var book=f.books.create(f.sales,input,"hundred",UUID.randomUUID());assertThat(book.entries()).hasSize(100);assertThat(book.entries()).allSatisfy(e->assertThat(e.unitAmount()).isEqualTo("1.00"));assertThat(f.books.list(f.sales,new PricingValues.Query("RETAIL","NGN",0,100,"code,asc")).items().stream().filter(b->b.id().equals(book.id())).findFirst().orElseThrow().entries()).hasSize(100);entries.add(new PricingValues.Entry(f.sku,"101","1.00"));var tooMany=new PricingValues.Input(null,"NGN","RETAIL",base.effectiveFrom().plusSeconds(1),base.effectiveUntil(),entries);assertThatThrownBy(()->f.books.revise(f.sales,book.id(),0,tooMany,"hundred-one",UUID.randomUUID())).hasMessage("PRICING_RULE_VIOLATION");}

}
